import{_ as l,a0 as o,w as d,s as r,I as t,x as s,a1 as i,A as e,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"ninja：一個簡單的構建方式 | LCTT x X-CMD","titleTemplate":false,"description":"ninja：一個簡單的構建方式 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ninja：一個簡單的構建方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ninja：一個簡單的構建方式 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201026 ninja- a simple way to do builds","title":"ninja：一個簡單的構建方式","tag":"202011","desc":""},"relativePath":"202011/20201026 ninja- a simple way to do builds.md","filePath":"[post].md"}'),u={name:"202011/20201026 ninja- a simple way to do builds.md"};function f(g,n,b,h,m,k){const a=o("Link");return d(),r("div",null,[n[32]||(n[32]=t("h1",{id:"ninja-一個簡單的構建方式",tabindex:"-1"},[s("ninja：一個簡單的構建方式 "),t("a",{class:"header-anchor",href:"#ninja-一個簡單的構建方式","aria-label":"Permalink to “ninja：一個簡單的構建方式”"},"​")],-1)),t("p",null,[n[1]||(n[1]=s("大家好！每隔一段時間，我就會發現一款我非常喜歡的新軟件，今天我想説説我最近喜歡的一款軟件：",-1)),i(a,{href:"https://ninja-build.org/"},{default:e(()=>[...n[0]||(n[0]=[s("ninja",-1)])]),_:1}),n[2]||(n[2]=s("！",-1))]),n[33]||(n[33]=p(`<h3 id="增量構建很有用" tabindex="-1">增量構建很有用 <a class="header-anchor" href="#增量構建很有用" aria-label="Permalink to “增量構建很有用”">​</a></h3><p>我做了很多小項目，在這些項目中，我想設置增量構建。例如，現在我正在寫一本關於 bash 的雜誌，雜誌的每一頁都有一個 <code>.svg</code>文件。我需要將 SVG 轉換為 PDF，我的做法是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in *.svg</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    svg2pdf $i $i.pdf # or \${i/.svg/.pdf} if you want to get really fancy</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>這很好用，但是我的 <code>svg2pdf</code> 腳本有點慢（它使用 Inkscape），而且當我剛剛只更新了一頁的時候，必須等待 90 秒或者其他什麼時間來重建所有的 PDF 文件，這很煩人。</p><h3 id="構建系統是讓人困惑的" tabindex="-1">構建系統是讓人困惑的 <a class="header-anchor" href="#構建系統是讓人困惑的" aria-label="Permalink to “構建系統是讓人困惑的”">​</a></h3><p>在過去，我對使用 <code>make</code> 或 <code>bazel</code> 這樣的構建系統來做我的小項目一直很反感，因為 <code>bazel</code> 是個大而複雜的東西，而 <code>make</code> 對我來説感覺有點神秘。我真的不想使用它們中的任何一個。</p><p>所以很長時間以來，我只是寫了一個 bash 腳本或者其他的東西來進行構建，然後就認命了，有時候只能等一分鐘。</p><h3 id="ninja-是一個極其簡單的構建系統" tabindex="-1">ninja 是一個極其簡單的構建系統 <a class="header-anchor" href="#ninja-是一個極其簡單的構建系統" aria-label="Permalink to “ninja 是一個極其簡單的構建系統”">​</a></h3><p>但 <code>ninja</code> 並不複雜！以下是我所知道的關於 ninja 構建文件的語法：創建一個 <code>rule</code> 和一個 <code>build</code>：</p><p><code>rule</code> 有一個命令（<code>command</code>）和描述（<code>description</code>）參數（描述只是給人看的，所以你可以知道它在構建你的代碼時在做什麼）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rule svg2pdf</span></span>
<span class="line"><span>  command = inkscape $in --export-text-to-path --export-pdf=$out</span></span>
<span class="line"><span>  description = svg2pdf $in $out</span></span></code></pre></div><p><code>build</code> 的語法是 <code>build output_file: rule_name input_files</code>。下面是一個使用 <code>svg2pdf</code> 規則的例子。輸出在規則中的 <code>$out</code> 裏，輸入在 <code>$in</code> 裏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>build pdfs/variables.pdf: svg2pdf variables.svg</span></span></code></pre></div><p>這就完成了！如果你把這兩個東西放在一個叫 <code>build.ninja</code> 的文件裏，然後運行 <code>ninja</code>，ninja 會運行 <code>inkscape variables.svg --export-text-to-path --export-pdf=pdfs/variables.pdf</code>。然後如果你再次運行它，它不會運行任何東西（因為它可以告訴你已經構建了 <code>pdfs/variables.pdf</code>，而且是最新的）。</p>`,14)),t("p",null,[n[5]||(n[5]=s("Ninja 還有一些更多的功能（見",-1)),i(a,{href:"https://ninja-build.org/manual.html"},{default:e(()=>[...n[3]||(n[3]=[s("手冊",-1)])]),_:1}),n[6]||(n[6]=s("），但我還沒有用過。它最初是",-1)),i(a,{href:"http://neugierig.org/software/chromium/notes/2011/02/ninja.html"},{default:e(()=>[...n[4]||(n[4]=[s("為 Chromium",-1)])]),_:1}),n[7]||(n[7]=s(" 構建的，所以即使只有一個小的功能集，它也能支持大型構建。",-1))]),n[34]||(n[34]=p(`<h3 id="ninja-文件通常是自動生成的" tabindex="-1">ninja 文件通常是自動生成的 <a class="header-anchor" href="#ninja-文件通常是自動生成的" aria-label="Permalink to “ninja 文件通常是自動生成的”">​</a></h3><p>ninja 的神奇之處在於，你不必使用一些混亂的構建語言，它們很難記住，因為你不經常使用它（比如 <code>make</code>），相反，ninja 語言超級簡單，如果你想做一些複雜的事情，那麼你只需使用任意編程語言生成你想要的構建文件。</p><p>我喜歡寫一個 <code>build.py</code> 文件，或者像這樣的文件，創建 ninja 的構建文件，然後運行 <code>ninja</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(&#39;build.ninja&#39;, &#39;w&#39;) as ninja_file:</span></span>
<span class="line"><span>    # write some rules</span></span>
<span class="line"><span>    ninja_file.write(&quot;&quot;&quot;</span></span>
<span class="line"><span>rule svg2pdf</span></span>
<span class="line"><span>  command = inkscape $in --export-text-to-path --export-pdf=$out</span></span>
<span class="line"><span>  description = svg2pdf $in $out</span></span>
<span class="line"><span>&quot;&quot;&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # some for loop with every file I need to build</span></span>
<span class="line"><span>    for filename in things_to_convert:</span></span>
<span class="line"><span>        ninja_file.write(f&quot;&quot;&quot;</span></span>
<span class="line"><span>build {filename.replace(&#39;svg&#39;, &#39;pdf&#39;)}: svg2pdf {filename}</span></span>
<span class="line"><span>&quot;&quot;&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run ninja</span></span>
<span class="line"><span>import subprocess</span></span>
<span class="line"><span>subprocess.check_call([&#39;ninja&#39;])</span></span></code></pre></div><p>我相信有一堆 <code>ninja</code> 的最佳實踐，但我不知道。對於我的小項目而言，我發現它很好用。</p><h3 id="meson-是一個生成-ninja-文件的構建系統" tabindex="-1">meson 是一個生成 ninja 文件的構建系統 <a class="header-anchor" href="#meson-是一個生成-ninja-文件的構建系統" aria-label="Permalink to “meson 是一個生成 ninja 文件的構建系統”">​</a></h3>`,6)),t("p",null,[n[10]||(n[10]=s("我對 ",-1)),i(a,{href:"https://mesonbuild.com/Tutorial.html"},{default:e(()=>[...n[8]||(n[8]=[s("Meson",-1)])]),_:1}),n[11]||(n[11]=s(" 還不太瞭解，但最近我在構建一個 C 程序 （",-1)),i(a,{href:"https://blog.sesse.net/blog/tech/2020-09-28-00-37_introducing_plocate"},{default:e(()=>[...n[9]||(n[9]=[s("plocate",-1)])]),_:1}),n[12]||(n[12]=s("，一個比 ",-1)),n[13]||(n[13]=t("code",null,"locate",-1)),n[14]||(n[14]=s(" 更快的替代方案）時，我注意到它有不同的構建説明，而不是通常的 ",-1)),n[15]||(n[15]=t("code",null,"./configure; make; make install",-1)),n[16]||(n[16]=s("：",-1))]),n[35]||(n[35]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>meson builddir</span></span>
<span class="line"><span>cd builddir</span></span>
<span class="line"><span>ninja</span></span></code></pre></div><p>看起來 Meson 是一個可以用 ninja 作為後端的 C/C++/Java/Rust/Fortran 構建系統。</p><h3 id="就是這些" tabindex="-1">就是這些！ <a class="header-anchor" href="#就是這些" aria-label="Permalink to “就是這些！”">​</a></h3><p>我使用 ninja 已經有幾個月了。我真的很喜歡它，而且它幾乎沒有給我帶來讓人頭疼的構建問題，這讓我感覺非常神奇。</p><hr>`,5)),t("p",null,[n[18]||(n[18]=s("via: ",-1)),i(a,{href:"https://jvns.ca/blog/2020/10/26/ninja--a-simple-way-to-do-builds/"},{default:e(()=>[...n[17]||(n[17]=[s("https://jvns.ca/blog/2020/10/26/ninja--a-simple-way-to-do-builds/",-1)])]),_:1})]),t("p",null,[n[23]||(n[23]=s("作者：",-1)),i(a,{href:"https://jvns.ca/"},{default:e(()=>[...n[19]||(n[19]=[s("Julia Evans",-1)])]),_:1}),n[24]||(n[24]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[20]||(n[20]=[s("lujun9972",-1)])]),_:1}),n[25]||(n[25]=s(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[21]||(n[21]=[s("geekpi",-1)])]),_:1}),n[26]||(n[26]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),t("p",null,[n[29]||(n[29]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[27]||(n[27]=[s("LCTT",-1)])]),_:1}),n[30]||(n[30]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...n[28]||(n[28]=[s("Linux中國",-1)])]),_:1}),n[31]||(n[31]=s(" 榮譽推出",-1))])])}const T=l(u,[["render",f]]);export{v as __pageData,T as default};
